// Bundled subsets of the omarsoliman.dev type system, base64-encoded.
//
// These are registered with FontFace(name, ArrayBuffer) — a constructor that takes BYTES, not a URL.
// That matters: the drawer runs in the MAIN world, so a url()-based @font-face would be subject to
// the ETA portal's Content-Security-Policy (the same policy that forced csp-shim.js to exist) and
// would silently fail. Constructing from bytes performs no fetch, so there is nothing for a CSP
// font-src directive to refuse.
//
// Subsets: latin for display and mono, arabic for the RTL UI face. Weights are trimmed to what the
// drawer actually renders. Regenerate with scratchpad/getfonts.mjs if the type system changes.
export const FONT_BLOBS = [{"family":"Bricolage Grotesque","weight":"400 800","b64":""},{"family":"IBM Plex Mono","weight":"400","b64":""},{"family":"IBM Plex Mono","weight":"600","b64":""},{"family":"IBM Plex Sans Arabic","weight":"400","b64":""},{"family":"IBM Plex Sans Arabic","weight":"600","b64":""}];
